import { useState } from 'react';
import { Screen, Card, Grid, Stack, Row, TextField, Button, Badge, Alert, KeyBar } from '@nexti/ds';

type Msg = { tone: 'info' | 'success' | 'warning' | 'error'; text: string } | null;

const MENU = [
  { value: '1', label: 'Pagar una orden', target: 'SCR-PAGOORD' },
  { value: '2', label: 'Consultar una orden', target: 'SCR-PAGORES' },
];

export default function PagoMenu({ navigate }: { navigate: (to: string) => void }) {
  const [opcion, setOpcion] = useState('');
  const [error, setError] = useState<string | undefined>(undefined);
  const [mensaje, setMensaje] = useState<Msg>(null);
  const [salio, setSalio] = useState(false);

  const fecha = '15/03/25'; // format 99/99/99

  const handleChange = (v: string) => {
    // numeric field, maximum length 1
    const clean = v.replace(/\D/g, '').slice(0, 1);
    setOpcion(clean);
    setError(undefined);
    setMensaje(null);
  };

  const continuar = () => {
    if (salio) return;
    if (opcion === '') {
      setError('La opción es obligatoria');
      setMensaje({ tone: 'error', text: 'Ingrese una opción (1 o 2) y presione Enter.' });
      return;
    }
    const sel = MENU.find((m) => m.value === opcion);
    if (!sel) {
      setError('Opción inválida');
      setMensaje({ tone: 'error', text: 'Opción inválida. Ingrese 1 para pagar o 2 para consultar una orden.' });
      return;
    }
    setError(undefined);
    setMensaje({ tone: 'success', text: `Opción ${sel.value} aceptada: ${sel.label}.` });
    navigate(sel.target);
  };

  const salir = () => {
    setSalio(true);
    setOpcion('');
    setError(undefined);
    setMensaje({ tone: 'info', text: 'Sesión finalizada. Puede cerrar esta pantalla.' });
  };

  const volver = () => {
    setSalio(false);
    setMensaje(null);
  };

  const onKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      continuar();
    } else if (e.key === 'F3') {
      e.preventDefault();
      salir();
    }
  };

  return (
    <Screen
      title="Banco ficticio - Pagos"
      code="PAGOMEN"
      keys={
        <KeyBar
          actions={[
            { key: 'ENTER', label: 'Continuar', onPress: continuar, primary: true },
            { key: 'PF3', label: 'Salir', onPress: salir },
          ]}
        />
      }
    >
      <div onKeyDown={onKeyDown}>
        <Stack>
          <Row>
            <span>Fecha:</span>
            <div data-field="FECHA">
              <Badge>{fecha}</Badge>
            </div>
          </Row>

          <Grid columns={2}>
            <Card title="Menú de pagos">
              <Stack>
                {MENU.map((m) => (
                  <Button
                    key={m.value}
                    variant={opcion === m.value ? 'primary' : 'ghost'}
                    onClick={() => handleChange(m.value)}
                  >
                    {`${m.value}. ${m.label}`}
                  </Button>
                ))}
              </Stack>
            </Card>

            <Card
              title="Selección"
              actions={
                salio ? (
                  <Button variant="secondary" onClick={volver}>
                    Volver al menú
                  </Button>
                ) : (
                  <Button variant="primary" shortcut="ENTER" onClick={continuar}>
                    Continuar
                  </Button>
                )
              }
            >
              <div data-field="OPCION">
                <TextField
                  label="Opción"
                  required
                  numeric
                  maxLength={1}
                  hint="Ingrese 1 o 2"
                  error={error}
                  value={opcion}
                  onChange={handleChange}
                  readOnly={salio}
                />
              </div>
            </Card>
          </Grid>

          <div data-field="MENSAJE" aria-live="polite">
            {mensaje ? (
              <Alert tone={mensaje.tone}>{mensaje.text}</Alert>
            ) : (
              <Alert tone="info">Seleccione una opción y presione Enter para continuar.</Alert>
            )}
          </div>
        </Stack>
      </div>
    </Screen>
  );
}
